from __future__ import annotations

import pytest

from llm_router._internal.providers.retry import (
    RetryClassification,
    classify_exception,
)

pytestmark = pytest.mark.verification_kind("unit")


@pytest.mark.verifies("TREQ_PROVIDER_RETRY_CLASSIFICATION[revision==1]")
def test_unrelated_retry_like_exception_is_rejected() -> None:
    decision = classify_exception(ValueError("connection reset by peer"))

    assert decision.classification is RetryClassification.NON_RETRYABLE
    assert not decision.retryable
